import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Clock, ChevronLeft, ChevronRight, Play } from 'lucide-react';
import { Header } from '../components/Header';
import { Footer } from '../components/Footer';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Separator } from '../components/ui/separator';
import { SEO } from '../components/SEO';
import { getTemplateBySlug, formatPrice } from '../data/templates';
import { useRazorpay } from '../hooks/useRazorpay';
import { Toaster } from 'sonner';

export default function TemplateDetailPage() {
  const { slug } = useParams();
  const template = getTemplateBySlug(slug);
  const { initiatePayment } = useRazorpay();
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [showFloatingBar, setShowFloatingBar] = useState(false);
  const purchaseSectionRef = useRef(null);
  // Initialize timer from localStorage or set new end time
  const [timeLeft, setTimeLeft] = useState(() => {
    const storageKey = `sale_timer_${slug}`;
    const storedEndTime = localStorage.getItem(storageKey);

    if (storedEndTime) {
      const remaining = Math.floor((parseInt(storedEndTime, 10) - Date.now()) / 1000);
      return remaining > 0 ? remaining : 0;
    } else {
      // Set new end time 30 minutes from now
      const endTime = Date.now() + 30 * 60 * 1000;
      localStorage.setItem(storageKey, endTime.toString());
      return 30 * 60;
    }
  });

  // Countdown timer for sale
  useEffect(() => {
    if (timeLeft <= 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  // Format time as MM:SS
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Show floating bar when purchase section is scrolled out of view (mobile only)
  useEffect(() => {
    const handleScroll = () => {
      if (purchaseSectionRef.current) {
        const rect = purchaseSectionRef.current.getBoundingClientRect();
        // Show floating bar when purchase section is above the viewport
        setShowFloatingBar(rect.bottom < 0);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (!template) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header />
        <main className="flex-1 flex items-center justify-center pt-16">
          <div className="text-center">
            <h1 className="text-2xl font-bold mb-4">Template not found</h1>
            <Link to="/products">
              <Button variant="brutal">Back to Products</Button>
            </Link>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  const handleBuyNow = () => {
    initiatePayment(template);
  };

  // Get all images - use images array if available, otherwise fall back to single image
  const allImages = template.images && template.images.length > 0
    ? template.images
    : [template.image];

  const hasMultipleImages = allImages.length > 1;

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length);
  };

  const seoTitle = `${template.name} - ${template.discount}% OFF`;
  const seoDescription = `${template.description} Only ${formatPrice(template.price)} (was ${formatPrice(template.originalPrice)}). ${template.includes.slice(0, 3).join('. ')}.`;
  const seoKeywords = [
    template.name.toLowerCase(),
    ...template.techStack.map(t => t.toLowerCase()),
    'automation workflows',
    'workflow templates',
    template.slug.replace(/-/g, ' ')
  ].join(', ');

  return (
    <div className="min-h-screen flex flex-col">
      <SEO
        title={seoTitle}
        description={seoDescription}
        keywords={seoKeywords}
        image={`https://syntheight.com${template.image}`}
        url={`https://syntheight.com/template/${template.slug}`}
        type="product"
      />
      <Header />

      {/* Floating Sale Timer - Fixed below header */}
      {timeLeft > 0 && (
        <div className="fixed top-16 left-0 right-0 z-40 flex items-center justify-center gap-2 py-2 bg-red-600 text-white shadow-lg">
          <Clock className="w-4 h-4 animate-pulse" />
          <p className="text-sm font-medium">
            Sale ends in <span className="font-bold tabular-nums bg-red-700 px-2 py-0.5 rounded">{formatTime(timeLeft)}</span>
          </p>
        </div>
      )}

      <main className={`flex-1 ${timeLeft > 0 ? 'pt-[96px]' : 'pt-16'}`}>
        {/* Back Link */}
        <div className="container-slate py-4">
          <Link
            to="/products"
            className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground py-2"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Products
          </Link>
        </div>

        {/* Template Content */}
        <div className="container-slate pb-24">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-14">
            {/* Left - Image Gallery */}
            <div className="space-y-4">
              {/* Badge */}
              {template.badge && (
                <Badge
                  variant="secondary"
                  className="bg-foreground text-background text-xs font-medium px-2.5 py-1 mb-2"
                >
                  {template.badge}
                </Badge>
              )}

              {/* Main Image with Navigation */}
              <div className="relative border border-border bg-secondary">
                {/* Image - natural aspect ratio */}
                <img
                  src={allImages[currentImageIndex]}
                  alt={`${template.name} - Image ${currentImageIndex + 1}`}
                  className="w-full h-auto"
                />

                {/* Navigation Arrows */}
                {hasMultipleImages && (
                  <>
                    <button
                      onClick={prevImage}
                      className="absolute left-2 top-1/2 -translate-y-1/2 w-10 h-10 bg-background/90 hover:bg-background border border-border flex items-center justify-center transition-colors"
                      aria-label="Previous image"
                    >
                      <ChevronLeft className="w-5 h-5" />
                    </button>
                    <button
                      onClick={nextImage}
                      className="absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 bg-background/90 hover:bg-background border border-border flex items-center justify-center transition-colors"
                      aria-label="Next image"
                    >
                      <ChevronRight className="w-5 h-5" />
                    </button>
                  </>
                )}

                {/* Image Counter */}
                {hasMultipleImages && (
                  <div className="absolute bottom-3 left-1/2 -translate-x-1/2 bg-background/90 border border-border px-3 py-1 text-xs font-medium">
                    {currentImageIndex + 1} / {allImages.length}
                  </div>
                )}
              </div>

              {/* Thumbnail Strip */}
              {hasMultipleImages && (
                <div className="flex gap-2 overflow-x-auto pb-2">
                  {allImages.map((img, index) => (
                    <button
                      key={index}
                      onClick={() => setCurrentImageIndex(index)}
                      className={`flex-shrink-0 w-20 h-20 border-2 overflow-hidden transition-all ${
                        index === currentImageIndex
                          ? 'border-foreground'
                          : 'border-border hover:border-muted-foreground'
                      }`}
                    >
                      <img
                        src={img}
                        alt={`Thumbnail ${index + 1}`}
                        className="w-full h-full object-cover"
                      />
                    </button>
                  ))}
                </div>
              )}

              {/* Video Tutorial */}
              <div className="mt-6">
                <div className="flex items-center gap-2 mb-3">
                  <Play className="w-4 h-4 text-muted-foreground" />
                  <h3 className="text-sm font-semibold">Video Tutorial</h3>
                </div>
                <div className="relative w-full border border-border bg-secondary" style={{ paddingBottom: '56.25%' }}>
                  <iframe
                    className="absolute top-0 left-0 w-full h-full"
                    src="https://www.youtube.com/embed/N4BOqPjOYOY"
                    title="Product Tutorial"
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                    allowFullScreen
                  />
                </div>
              </div>

            </div>

            {/* Right - Details */}
            <div>
              {/* Header */}
              <div className="mb-5">
                <p className="text-xs text-muted-foreground uppercase tracking-wider mb-2">
                  {template.bestFor}
                </p>
                <h1 className="text-2xl sm:text-3xl font-bold tracking-tight mb-2">
                  {template.name}
                </h1>
                <p className="text-sm text-muted-foreground leading-relaxed">
                  {template.description}
                </p>
              </div>

              {/* Quick Stats */}
              <div className="flex items-center gap-4 mb-5 text-sm">
                <div className="flex items-center gap-2">
                  <Clock className="w-4 h-4 text-muted-foreground" />
                  <span>{template.customizeTime} to customize</span>
                </div>
              </div>

              <Separator className="my-5" />

              {/* Included */}
              <div className="mb-5">
                <h2 className="text-sm font-semibold mb-2">What You Get</h2>
                <ul className="space-y-1.5">
                  {template.includes.map((item, index) => (
                    <li key={index} className="flex items-center gap-2 text-sm text-muted-foreground">
                      <span className="w-1 h-1 bg-foreground flex-shrink-0 rounded-full" />
                      {item}
                    </li>
                  ))}
                </ul>
              </div>

              <Separator className="my-5" />

              {/* Who This Is NOT For */}
              <div className="mb-5 p-4 bg-secondary/50 border border-border">
                <h2 className="text-sm font-semibold mb-1">Not For You If</h2>
                <p className="text-xs text-muted-foreground">
                  {template.notFor}
                </p>
              </div>

              {/* Tech Stack & File Formats */}
              <div className="grid grid-cols-2 gap-4 mb-5">
                <div>
                  <h2 className="text-sm font-semibold mb-2">Tech Stack</h2>
                  <div className="flex flex-wrap gap-1.5">
                    {template.techStack.map((tech, index) => (
                      <Badge
                        key={index}
                        variant="secondary"
                        className="bg-secondary text-secondary-foreground text-[10px] px-2 py-0.5"
                      >
                        {tech}
                      </Badge>
                    ))}
                  </div>
                </div>
                <div>
                  <h2 className="text-sm font-semibold mb-2">Files Included</h2>
                  <div className="flex flex-wrap gap-1.5">
                    {template.fileFormats.map((format, index) => (
                      <Badge
                        key={index}
                        variant="secondary"
                        className="bg-secondary text-secondary-foreground text-[10px] px-2 py-0.5"
                      >
                        {format}
                      </Badge>
                    ))}
                  </div>
                </div>
              </div>

              <Separator className="my-5" />

              {/* What Happens After Purchase */}
              <div className="mb-5">
                <h2 className="text-sm font-semibold mb-2">After Purchase</h2>
                <div className="space-y-2">
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 bg-foreground text-background flex items-center justify-center text-[10px] font-bold flex-shrink-0">
                      1
                    </div>
                    <p className="text-xs text-muted-foreground">Instant download link via email</p>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 bg-foreground text-background flex items-center justify-center text-[10px] font-bold flex-shrink-0">
                      2
                    </div>
                    <p className="text-xs text-muted-foreground">Unzip and open in any code editor</p>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 bg-foreground text-background flex items-center justify-center text-[10px] font-bold flex-shrink-0">
                      3
                    </div>
                    <p className="text-xs text-muted-foreground">Email support if you get stuck</p>
                  </div>
                </div>
              </div>

              <Separator className="my-5" />

              {/* Purchase Section */}
              <div
                ref={purchaseSectionRef}
                className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 sm:p-5 bg-secondary"
              >
                <div>
                  <p className="text-xs text-muted-foreground mb-1">One-time purchase</p>
                  <div className="flex items-center gap-3">
                    <p className="text-2xl sm:text-3xl font-bold">{formatPrice(template.price)}</p>
                    {template.originalPrice && (
                      <div className="flex flex-col">
                        <span className="text-sm text-muted-foreground line-through">
                          {formatPrice(template.originalPrice)}
                        </span>
                        <span className="text-xs text-green-600 font-medium">
                          Save {template.discount}%
                        </span>
                      </div>
                    )}
                  </div>
                  <p className="text-[10px] text-muted-foreground mt-1">
                    Limited time offer • Cheaper than 1 hour of developer time
                  </p>
                </div>
                <Button
                  variant="brutal"
                  size="lg"
                  onClick={handleBuyNow}
                  className="w-full sm:w-auto"
                >
                  Buy Now
                </Button>
              </div>

              <p className="text-xs text-muted-foreground mt-3 text-center sm:text-left">
                Secure payment via Razorpay. Instant download.
              </p>
            </div>
          </div>
        </div>
      </main>

      {/* Mobile Floating Purchase Bar */}
      <div
        className={`lg:hidden fixed bottom-0 left-0 right-0 z-40 bg-background border-t border-border px-4 py-4 transition-transform duration-300 ${
          showFloatingBar ? 'translate-y-0' : 'translate-y-full'
        }`}
      >
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <p className="text-2xl font-bold">{formatPrice(template.price)}</p>
            {template.originalPrice && (
              <div className="flex items-center gap-2">
                <span className="text-base text-muted-foreground line-through">
                  {formatPrice(template.originalPrice)}
                </span>
                <span className="text-sm text-green-600 font-medium">
                  {template.discount}% OFF
                </span>
              </div>
            )}
          </div>
          <Button
            variant="brutal"
            size="lg"
            onClick={handleBuyNow}
            className="flex-shrink-0"
          >
            Buy Now
          </Button>
        </div>
      </div>

      <Footer />
      <Toaster position="top-center" />
    </div>
  );
}
